INSERT IGNORE INTO task_instructions (task_type_id, instruction_name, language, instructions_json)
SELECT task_type_id, 'EN_Instructions_DefaultB', 'EN', '{"WelcomeText":[{"page":"Welcome to the Trail Making Task.</p>"}],"PracticePrompt":[{"page":"First, you will perform a practice test."}],"RealTaskPrompt":[{"page":"Press <b>Next</b> to begin the task."}],"Instructions":[{"page":"For this task you will see  numbers and letters in circles. Please, draw a line switching in order between numbers and letters. Start at number 1, then go to letter A, then go to number 2, and then the next letter B, and so on. Continue in order, until you reach the letter labeled end."},{"page":"Draw your line as fast as you can. When your line enters a correct circle it will change color, indicating that this is the next correct circle in the sequence.</br> If the circle does not change color, you have made a mistake and need to draw your line to a different circle."}],"InstructionsShownWithPractice":"Begin at number 1 and draw a line from 1 to A, A to 2, 2 to B and so on, in order, until you reach the letter labeled end.<br/>Draw your line as fast as you can. When your line enters a correct circle it will change color, indicating that this is the next correct circle in the sequence.</br> If the circle does not change color, you have made a mistake and need to draw your line to a different circle.","ThankYouText":[{"page":"Thank you."}],"NotesForResultsPage":"The provided Response Time is how long it took to complete the entire trail and press the Finish button. Note that thios time is in milliseconds. The errors refer to the number of times a participant drew a trail to a number/letter that was not the next correct item.","FirstCircleLabel":"begin","LastCircleLabel":"end","FinishedLabel":"Finished"}'
FROM task_types WHERE task_name = 'Trail Making';

