INSERT IGNORE INTO task_instructions (task_type_id, instruction_name, language, instructions_json)
SELECT task_type_id, 'FR_Instructions_DefaultA', 'FR', '{"WelcomeText":[{"page":"C''est la tâche de Sentiers"}],"PracticePrompt":[{"page":"Tout d''abord, vous effectuerez un test pratique."}],"RealTaskPrompt":[{"page":"Appuyez sur <b>Suivant</b> pour Continuer."}],"Instructions":[{"page":"Pour cette tâche, vous verrez des nombres dans des cercles. Veuillez tracer une ligne d''un nombre à l''autre, dans l''ordre. Commencez à 1, puis passez à 2, puis passez à 3, et ainsi de suite. Continuez jusqu''à ce que vous atteigniez le numéro marqué end."},{"page":"Tracez votre ligne aussi vite que vous le pouvez. Lorsque votre ligne entre dans un cercle correct, elle change de couleur, indiquant qu''il s''agit du prochain cercle correct dans la séquence.</br> Si le cercle ne change pas de couleur, vous avez fait une erreur et devez tracer votre ligne vers un autre cercle."}],"InstructionsShownWithPractice":"Commencez au numéro 1 et tracez une ligne de 1 à 2, 2 à 3, 3 à 4 et ainsi de suite, dans l''ordre, jusqu''à ce que vous atteigniez le chiffre marqué fin.</br> Tracez votre ligne aussi vite que vous le pouvez. Lorsque votre ligne entre dans un cercle correct, elle change de couleur, indiquant qu''il s''agit du prochain cercle correct dans la séquence.</br> Si le cercle ne change pas de couleur, vous avez fait une erreur et devez tracer votre ligne vers un autre cercle","ThankYouText":[{"page":"Merci"}],"NotesForResultsPage":"FR: The provided Response Time is how long it took to complete the entire trail and press the Finish button. Note that thios time is in milliseconds. The errors refer to the number of times a participant drew a trail to a number/letter that was not the next correct item.","FirstCircleLabel":"commencer","LastCircleLabel":"fin","FinishedLabel":"Fini","TimeRemainingLabel":"restant"}'
FROM task_types WHERE task_name = 'Trail Making';

INSERT IGNORE INTO task_instructions (task_type_id, instruction_name, language, instructions_json)
SELECT task_type_id, 'FR_Instructions_DefaultB', 'FR', '{"WelcomeText":[{"page":"C''est la tâche de Sentiers"}],"PracticePrompt":[{"page":"Tout d''abord, vous effectuerez un test pratique."}],"RealTaskPrompt":[{"page":"Appuyez sur <b>Suivant</b> pour Continuer."}],"Instructions":[{"page":"Pour cette tâche, vous verrez des chiffres et des lettres dans des cercles. Veuillez tracer une ligne alternant dans l''ordre entre les chiffres et les lettres. Commencez au numéro 1, puis passez à la lettre A, puis passez au numéro 2, puis à la lettre B suivante, et ainsi de suite. Continuez dans l''ordre, jusqu''à ce que vous atteigniez la lettre marquée fin."},{"page":"Tracez votre ligne aussi vite que vous le pouvez. Lorsque votre ligne entre dans un cercle correct, elle change de couleur, indiquant qu''il s''agit du prochain cercle correct dans la séquence.</br> Si le cercle ne change pas de couleur, vous avez fait une erreur et devez tracer votre ligne vers un autre cercle."}],"InstructionsShownWithPractice":"Commencez au numéro 1 et tracez une ligne de 1 à A, A à 2, 2 à B et ainsi de suite, dans l''ordre, jusqu''à ce que vous atteigniez la lettre étiquetée end.<br/>Trace votre ligne aussi vite que possible. Lorsque votre ligne entre dans un cercle correct, elle change de couleur, indiquant qu''il s''agit du prochain cercle correct dans la séquence.</br> Si le cercle ne change pas de couleur, vous avez fait une erreur et devez tracer votre ligne vers un autre cercle.","ThankYouText":[{"page":"Merci"}],"NotesForResultsPage":"FR: The provided Response Time is how long it took to complete the entire trail and press the Finish button. Note that thios time is in milliseconds. The errors refer to the number of times a participant drew a trail to a number/letter that was not the next correct item.","FirstCircleLabel":"commencer","LastCircleLabel":"fin","FinishedLabel":"Fini","TimeRemainingLabel":"restant"}'
